
import { z } from 'zod';

export const enqueueNotificationSchema = z.strictObject({
  userId: z.string().trim().min(1).max(191),

  templateId: z.string().trim().min(1).max(191),

  // Unique request key generated by the caller.
  // Repeating the same key never creates a second job.
  idempotencyKey: z.string()
    .trim()
    .regex(/^[A-Za-z0-9_-]{16,100}$/),

  locale: z.string().trim()
    .regex(/^[a-z]{2,3}(?:-[A-Za-z0-9]{2,8})*$/)
    .default('en'),

  variables: z.record(
    z.string().regex(/^[a-z][a-zA-Z0-9_]{0,49}$/),
    z.string().max(500),
  ).default({}),

  scheduledAt: z.iso.datetime().optional(),
});

export const notificationQueueListSchema = z.strictObject({
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100)
    .default(20),

  status: z.enum([
    'QUEUED',
    'PROCESSING',
    'SENT',
    'DELIVERED',
    'FAILED',
    'SKIPPED',
    'CANCELLED',
  ]).optional(),
});

export const deliveryIdSchema =
  z.string().trim().min(1).max(191);

export type EnqueueNotificationInput =
  z.infer<typeof enqueueNotificationSchema>;

export type NotificationQueueListInput =
  z.infer<typeof notificationQueueListSchema>;
